import { Router } from "express";
import { q } from "../db/index.js";
import { searchJobs } from "./public.js";

/**
 * MBONO Assistant chatbot.
 * - Always works offline: intent matching for FAQs + live vacancy search against the database.
 * - If ANTHROPIC_API_KEY or OPENAI_API_KEY is set, answers are generated by the AI model, grounded in the FAQ and live vacancies.
 */
export const chatRouter = Router();

interface Faq { id: string; keywords: string[]; answer: string; suggestions?: string[] }
const FAQ: Faq[] = [
  { id: "greet", keywords: ["hello", "hi", "hey", "good morning", "good afternoon", "sawubona", "molo", "howzit"], answer: "Hello! 👋 I'm the MBONO Assistant. I can help you find vacancies, explain how to apply, upload your CV, or reach our team. What are you looking for?", suggestions: ["Show me IT jobs", "How do I apply?", "Jobs in Gqeberha"] },
  { id: "apply", keywords: ["how do i apply", "how to apply", "apply for", "application process", "submit application"], answer: "Applying is easy:\n1. Sign up (free) as a candidate.\n2. Complete your profile and upload your CV (PDF/DOC, max 5 MB).\n3. Go to Vacancies, open a job and click **Apply**.\n4. Track progress under *My Applications* in your dashboard.", suggestions: ["How do I upload my CV?", "Track my application"] },
  { id: "register", keywords: ["register", "sign up", "signup", "create account", "create an account", "join"], answer: "Click **Sign Up** at the top of the page. Choose *Candidate* to look for work or *Recruiter* to post vacancies. Recruiter accounts are approved by an administrator before you can sign in.", suggestions: ["How do I apply?", "I am an employer"] },
  { id: "cv", keywords: ["cv", "resume", "résumé", "upload", "curriculum"], answer: "Sign in, open your **Candidate Dashboard → Profile & CV**, and upload your CV (PDF, DOC or DOCX up to 5 MB). You can also upload certifications there. A complete profile gets noticed faster!", suggestions: ["How do I apply?", "Profile completion tips"] },
  { id: "profile", keywords: ["profile completion", "complete my profile", "profile tips", "improve profile"], answer: "Fill in your headline, bio, skills, experience, education, phone and location, and upload a CV — each one raises your profile completion percentage on your dashboard.", suggestions: ["How do I upload my CV?"] },
  { id: "track", keywords: ["track", "status", "my application", "progress", "heard back", "update on"], answer: "Sign in and go to **Candidate Dashboard → My Applications**. Each application shows its status: Submitted → Under Review → Shortlisted → Interview → Offered/Hired. You'll also get an email and a notification whenever it changes.", suggestions: ["Interview invitations"] },
  { id: "interview", keywords: ["interview", "invitation", "invite"], answer: "When a recruiter schedules an interview you receive an email and a notification. All invitations (date, time, type and location/link) appear under **Interviews** in your candidate dashboard. Tip: research the company and prepare examples using the STAR method.", suggestions: ["Track my application"] },
  { id: "employer", keywords: ["employer", "recruiter", "post a job", "post jobs", "hire", "hiring staff", "advertise", "company"], answer: "Employers can **Sign Up as a Recruiter**. After admin approval you can post, edit and close vacancies, review applications, shortlist candidates, schedule interviews and search our candidate database.", suggestions: ["Contact details", "How long does approval take?"] },
  { id: "approval", keywords: ["approval", "approved", "pending", "awaiting"], answer: "Recruiter accounts are usually reviewed within one business day. You'll get an email as soon as your account is approved.", suggestions: ["Contact details"] },
  { id: "contact", keywords: ["contact", "phone", "email", "address", "office", "where are you", "location of office", "call"], answer: "", suggestions: ["Show me vacancies"] },
  { id: "fees", keywords: ["cost", "fee", "pay", "free", "charge", "price"], answer: "Registering and applying for jobs is **completely free** for candidates. Employers can contact us for recruitment service rates.", suggestions: ["Contact details"] },
  { id: "password", keywords: ["password", "forgot", "reset", "can't log in", "cannot log in", "login problem", "sign in problem"], answer: "Signed in? Change your password under your dashboard **Settings**. Forgot it? Use the Contact Us form or email us and our team will reset it for you.", suggestions: ["Contact details"] },
  { id: "saved", keywords: ["save job", "saved jobs", "favourite", "favorite", "bookmark"], answer: "Click the ♥ heart on any job card to save it. Saved jobs appear under **Saved Jobs** in your candidate dashboard.", suggestions: ["Show me vacancies"] },
  { id: "about", keywords: ["who are you", "about mbono", "what is mbono", "what do you do", "about us"], answer: "MBONO Recruitment Services connects skilled professionals with meaningful opportunities across South Africa, and helps companies recruit top talent through a transparent, people-first process.", suggestions: ["Show me vacancies", "How do I apply?"] },
  { id: "thanks", keywords: ["thank", "thanks", "ngiyabonga", "enkosi", "dankie"], answer: "You're welcome! Good luck with your job search. 🍀 Anything else I can help with?", suggestions: ["Show me vacancies"] },
];

const JOB_WORDS = ["job", "jobs", "vacancy", "vacancies", "position", "positions", "role", "roles", "opening", "openings", "work", "career", "careers", "opportunit", "hiring", "employment", "internship", "learnership", "graduate"];
const STOP = new Set(["show", "me", "find", "any", "are", "there", "in", "at", "for", "a", "an", "the", "i", "want", "need", "looking", "look", "search", "available", "please", "can", "you", "get", "some", "what", "is", "do", "have", "near", "around", "of", "to", "with", "jobs", "job", "vacancy", "vacancies", "position", "positions", "role", "roles", "work", "openings", "opening", "hiring", "careers", "career", "opportunities", "opportunity", "employment", "list", "all", "open", "new", "latest", "current", "currently", "your", "on", "my", "and", "or"]);
const ALIASES: Record<string, string> = { it: "information technology", tech: "information technology", developer: "developer", pe: "gqeberha", "port elizabeth": "gqeberha", jhb: "johannesburg", joburg: "johannesburg", cpt: "cape town", dbn: "durban", pta: "pretoria", nurse: "nurse", nursing: "healthcare", finance: "finance", accounting: "finance", sales: "sales", marketing: "marketing", hr: "human resources", engineering: "engineering", logistics: "logistics", "customer service": "customer service", "call centre": "customer service", "contact centre": "customer service" };

async function contactAnswer() {
  const c = Object.fromEntries((await q("SELECT key, value FROM site_content")).map(r => [r.key, r.value]));
  return `You can reach MBONO Recruitment Services here:\n📧 ${c.contact_email}\n📞 ${c.contact_phone}\n📍 ${c.contact_address}\n🕗 ${c.office_hours}\n\nOr use the form on our **Contact Us** page.`;
}

async function findJobs(message: string) {
  const text = message.toLowerCase();
  const filters = await q("SELECT DISTINCT location, province, industry, employment_type FROM jobs WHERE status = 'open'");
  let location: string | undefined, industry: string | undefined, type: string | undefined;
  for (const f of filters) {
    if (!location && text.includes(String(f.location).toLowerCase())) location = f.location;
    if (!location && text.includes(String(f.province).toLowerCase())) location = f.province;
    if (!industry && text.includes(String(f.industry).toLowerCase())) industry = f.industry;
    if (!type && text.includes(String(f.employment_type).toLowerCase())) type = f.employment_type;
  }
  for (const [alias, real] of Object.entries(ALIASES)) {
    if (new RegExp(`\\b${alias}\\b`).test(text)) {
      const ind = filters.find(f => String(f.industry).toLowerCase() === real);
      const loc = filters.find(f => String(f.location).toLowerCase() === real);
      if (ind && !industry) industry = ind.industry;
      if (loc && !location) location = loc.location;
    }
  }
  const used = [location, industry, type].filter(Boolean).join(" ").toLowerCase();
  const terms = text.replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter(w => w.length > 2 && !STOP.has(w) && !used.includes(w) && !ALIASES[w]);
  let jobs = await searchJobs({ location, industry, type });
  if (terms.length) {
    const narrowed = jobs.filter(j => terms.some(t => `${j.title} ${j.company} ${j.description} ${j.industry}`.toLowerCase().includes(t)));
    if (narrowed.length || location || industry || type) jobs = narrowed.length ? narrowed : jobs;
  }
  const filtered = !!(location || industry || type || terms.length);
  return { jobs: jobs.slice(0, 5), total: jobs.length, location, industry, type, filtered };
}

function wantsJobs(text: string) {
  return JOB_WORDS.some(w => text.includes(w)) || Object.keys(ALIASES).some(a => new RegExp(`\\b${a}\\b`).test(text));
}

async function ruleBased(message: string) {
  const text = message.toLowerCase().trim();
  // FAQ intents first (longest keyword match wins), unless it is clearly a job search.
  let best: Faq | undefined; let bestLen = 0;
  for (const f of FAQ) for (const k of f.keywords) {
    const hit = k.length <= 3 ? new RegExp(`\\b${k}\\b`).test(text) : text.includes(k);
    if (hit && k.length > bestLen) { best = f; bestLen = k.length; }
  }
  const jobIntent = wantsJobs(text) && !["apply", "track", "employer", "cv", "saved", "register"].includes(best?.id ?? "");
  if (jobIntent) {
    const r = await findJobs(message);
    if (!r.jobs.length) return { reply: "I couldn't find open vacancies matching that right now. Try a different keyword or location, or browse all vacancies. New jobs are added every week!", jobs: [], suggestions: ["Show all vacancies", "Jobs in Gauteng", "IT jobs"] };
    const what = [r.type, r.industry, r.location && `in ${r.location}`].filter(Boolean).join(" ");
    return { reply: `I found ${r.total} open vacanc${r.total === 1 ? "y" : "ies"}${what ? ` (${what})` : ""}. Here ${r.jobs.length === 1 ? "is" : "are the top"} ${r.jobs.length}:`, jobs: r.jobs, suggestions: ["How do I apply?", "Jobs in Cape Town", "Graduate programmes"] };
  }
  if (best) return { reply: best.id === "contact" ? await contactAnswer() : best.answer, jobs: [], suggestions: best.suggestions ?? [] };
  return { reply: "I'm not sure I understood that. I can help you **search vacancies** (e.g. \"finance jobs in Durban\"), explain **how to apply**, **upload your CV**, **track applications**, or give you our **contact details**.", jobs: [], suggestions: ["Show me vacancies", "How do I apply?", "Contact details"] };
}

async function aiAnswer(message: string, history: { role: string; content: string }[]) {
  const jobs = await searchJobs({});
  const context = `You are "MBONO Assistant", the friendly chatbot of MBONO Recruitment Services (South Africa). Be concise (max ~120 words), warm and professional. Use South African context (Rands, provinces).
Site features: Sign Up as candidate or recruiter (recruiters need admin approval). Candidates: profile, upload CV (PDF/DOC ≤5MB) and certifications, apply, save jobs (heart icon), track status (Submitted, Under Review, Shortlisted, Interview, Offered, Hired, Rejected), interview invitations by email. Recruiters: post/edit/delete vacancies, review applications, shortlist, schedule interviews, search candidates. Applying is free.
Contact: ${await contactAnswer()}
Current open vacancies (id | title | company | location | type | industry | salary | closes):
${jobs.map(j => `${j.id} | ${j.title} | ${j.company} | ${j.location}, ${j.province} | ${j.employment_type} | ${j.industry} | R${j.salary_min}-R${j.salary_max} | ${j.closing_date}`).join("\n")}
Only recommend vacancies from this list. Never invent jobs or contact details. If asked something unrelated to careers/recruitment, politely steer back.`;
  const msgs = [...history.slice(-8).filter(m => m.content), { role: "user", content: message }].map(m => ({ role: m.role === "assistant" ? "assistant" : "user", content: String(m.content).slice(0, 2000) }));
  if (process.env.ANTHROPIC_API_KEY) {
    const r = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "content-type": "application/json", "x-api-key": process.env.ANTHROPIC_API_KEY, "anthropic-version": "2023-06-01" },
      body: JSON.stringify({ model: process.env.ANTHROPIC_MODEL || "claude-haiku-4-5", max_tokens: 400, system: context, messages: msgs }),
    });
    if (!r.ok) throw new Error(`Anthropic ${r.status}`);
    const d: any = await r.json();
    return d.content?.map((c: any) => c.text).join("") as string;
  }
  const r = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${process.env.OPENAI_API_KEY}` },
    body: JSON.stringify({ model: process.env.OPENAI_MODEL || "gpt-4o-mini", max_tokens: 400, messages: [{ role: "system", content: context }, ...msgs] }),
  });
  if (!r.ok) throw new Error(`OpenAI ${r.status}`);
  const d: any = await r.json();
  return d.choices?.[0]?.message?.content as string;
}

chatRouter.post("/chat", async (req, res) => {
  const message = String(req.body?.message ?? "").trim().slice(0, 1000);
  if (!message) return res.status(400).json({ error: "Please type a message." });
  const history = Array.isArray(req.body?.history) ? req.body.history : [];
  const base = await ruleBased(message);
  if (process.env.ANTHROPIC_API_KEY || process.env.OPENAI_API_KEY) {
    try {
      const reply = await aiAnswer(message, history);
      if (reply) return res.json({ ...base, reply, ai: true });
    } catch (e) { console.warn("[chat] AI unavailable, using built-in answers:", (e as Error).message); }
  }
  res.json({ ...base, ai: false });
});
